ee:message.ee:set-payload:
%dw 2.0
output application/java

var doc = vars.parentFields

// Every field is wrapped as { value, confidenceScore, geometry, pageNumber }, and an
// unextracted one arrives present-but-null ("patient_id": { "value": null, ... }), so
// reach through to .value and treat "" as absent too.
fun f(key) = do {
    var v = doc[key].value
    ---
    if (v == null or (v is String and trim(v) == "")) null else v
}

// Dates arrive ISO ("2026-05-19", "1981-08-28"). The dotted MM.dd.yyyy form was what the
// previous document action emitted and is kept as a fallback, along with US slashes, so a
// reprocessed older extraction still maps rather than silently nulling out.
fun parseDate(key) = do {
    var v = f(key)
    ---
    if (v == null) null
    else ((v as String) as Date default
         ((v as String) as Date {format: "MM.dd.yyyy"} default
         ((v as String) as Date {format: "MM/dd/yyyy"} default null)))
}

fun cleanAmount(v) =
    if (v == null or (v is String and trim(v) == "")) null
    else ((v as String) replace "\$" with "" replace "," with "") as Number default null

// No total is extracted for pharmacy bills, so roll it up from the charge lines. Mirrors
// what the reviewer sees on the document itself.
var chargeTotal = sum(
    ((vars.lineItems default []) map ((item) -> cleanAmount(item.Charge_Amount.value)))
    filter ($ != null)
)
---
{
	name: vars.FullFileName default "Bill.pdf",
    RecordTypeId: vars.RecordTypeId,

    // Hardcoded rather than taken from fields.document_category: this is the pharmacy
    // endpoint, and Document_Category__c is a restricted picklist that would reject any
    // unexpected label IDP returned.
    Document_Category__c: "Pharmacy",

    Provider_Name__c: f("provider_name"),
    Facility_Name__c: f("facility_name"),
    Facility_Address__c: f("facility_address"),
    Facility_Phone__c: f("facility_phone"),
    Facility_Fax__c: f("facility_fax"),

    Date_of_Service__c: parseDate("date_of_service"),

    First_Name__c: f("first_name"),
    Last_Name__c: f("last_name"),
    Date_of_Birth__c: parseDate("date_of_birth"),

    Total_Charges_Extracted__c: if (chargeTotal == 0) null else chargeTotal,

    Matter__c: vars.matterId
}

%dw 2.0
output application/java

// One row per line item, each cell wrapped as { value, confidenceScore, geometry,
// pageNumber } - same envelope as the standalone fields. Column keys confirmed against a
// real execution: Description, Category, Service_Date, Units_Days, Charge_Amount, Line_Type.
var rows = vars.lineItems default []

fun cell(item, key) = do {
    var v = item[key].value
    ---
    if (v == null or (v is String and trim(v) == "")) null else v
}

fun cleanAmount(v) =
    if (v == null) null
    else ((v as String) replace "\$" with "" replace "," with "") as Number default null

// Service_Date arrives ISO ("2026-05-19"). MM.dd.yyyy was the previous document action's
// format and is kept as a fallback so a reprocessed older extraction still maps.
fun parseDate(v) =
    if (v == null) null
    else ((v as String) as Date default
         ((v as String) as Date {format: "MM.dd.yyyy"} default
         ((v as String) as Date {format: "MM/dd/yyyy"} default null)))

// Line_Type__c is a restricted picklist of exactly Charge and Adjustment (confirmed live,
// 2026-09-28). Anything unrecognised is left null rather than guessed at - a wrong value
// fails the whole insert, and the field is not required.
fun mapLineType(v) =
    if (v == null) null
    else lower(trim(v as String)) match {
        case "charge" -> "Charge"
        case "charges" -> "Charge"
        case "adjustment" -> "Adjustment"
        case "adjustments" -> "Adjustment"
        else -> null
    }

// Category__c is likewise restricted; "Pharmacy" is the right default for this endpoint,
// and it is what the extraction leaves null on every row today.
fun mapCategory(v) =
    if (v == null) "Pharmacy"
    else lower(trim(v as String)) match {
        case "pharmacy" -> "Pharmacy"
        case "laboratory" -> "Laboratory"
        case "radiology" -> "Radiology"
        case "emergency room" -> "Emergency Room"
        case "office visit" -> "Office Visit"
        else -> "Other"
    }
---
rows map (item) -> {
    // Parent Relationship Link
    Matter_Document__c: vars.matterDocumentId,

    Description__c: cell(item, "Description"),
    Category__c: mapCategory(cell(item, "Category")),
    Service_Date__c: parseDate(cell(item, "Service_Date")),
    Units_Days__c: if (cell(item, "Units_Days") != null) (cell(item, "Units_Days") as String) as Number default null else null,
    Charge_Amount__c: cleanAmount(cell(item, "Charge_Amount")),
    Line_Type__c: mapLineType(cell(item, "Line_Type"))
}

%dw 2.0 output application/java import * from dw::core::Strings
var caseNumStr = (vars.caseNumber default "") as String var folderList = payload.value default []
var matched = (folderList filter ((item) -> (item.folder != null) and (contains(item.name default "", caseNumStr) or endsWith(item.name default "", caseNumStr)) ))[0] --- matched default {}

salesforce:update.salesforce:records:
#[%dw 2.0
output application/java
---
[{
    Id: vars.matterDocumentId,
    // Neither Link__c nor Link_Text__c exist on Matter_Document__c in this
    // org (both confirmed live, 2026-09-16, via "No such column" errors).
    // Real field is Document_Link__c only -- Link_Text__c dropped rather
    // than guessing a second field name.
    Document_Link__c: vars.fileLink,
    Original_Document_Link__c: vars.fileLink
}]]
